  "inlineSchema": "// AI漫剧创作平台 数据模型\n// Provider: PostgreSQL\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ========== 枚举 ==========\n\nenum ProjectStatus {\n  DRAFT\n  SCRIPTING\n  ASSETING\n  STORYBOARDING\n  RENDERING\n  DONE\n}\n\nenum AssetType {\n  CHARACTER\n  SCENE\n  PROP\n  STYLE\n}\n\nenum AssetStatus {\n  DRAFTING\n  REVIEWING\n  APPROVED\n  REJECTED\n}\n\nenum TaskType {\n  LLM\n  IMAGE\n  VIDEO\n  TTS\n  MUSIC\n  SFX\n  COMPOSE\n}\n\nenum TaskStatus {\n  QUEUED\n  PROCESSING\n  DONE\n  FAILED\n  REJECTED\n}\n\nenum ShotStatus {\n  PENDING // 待生成\n  PROMPT_READY // 提示词就绪\n  IMAGE_GENERATING\n  IMAGE_DONE\n  IMAGE_FAILED\n  VIDEO_GENERATING\n  VIDEO_DONE\n  VIDEO_FAILED\n  VOICE_GENERATING\n  VOICE_DONE\n  VOICE_FAILED\n  COMPOSED\n  REJECTED\n}\n\n// ========== 核心模型 ==========\n\n/// 项目（一部漫剧）\nmodel Project {\n  id        String        @id @default(cuid())\n  title     String\n  status    ProjectStatus @default(DRAFT)\n  style     Json? // 全局风格锁定：{ styleDesc, styleRefImageId }\n  novelPath String? // 上传小说文件路径\n  novelText String?       @db.Text // 解析后的纯文本\n  novelMeta Json? // { chapters: [{index,title,start,end}] }\n  createdAt DateTime      @default(now())\n  updatedAt DateTime      @updatedAt\n\n  scripts    Script[]\n  characters Character[]\n  scenes     Scene[]\n  assets     Asset[]\n  episodes   Episode[]\n  tasks      GenTask[]\n\n  @@index([status])\n}\n\n/// 剧本（含梗概与结构化内容，支持版本）\nmodel Script {\n  id        String   @id @default(cuid())\n  projectId String\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  logline   String? // 核心梗概（一句话）\n  content   Json? // 结构化剧本：{ episodes: [{ number, title, hookEnd, scenes: [{ sceneId?, location, time, characters, action, dialogs: [{char, text, emotion}] }] }] }\n  status    String   @default(\"draft\") // draft | reviewing | approved\n  approved  Boolean  @default(false)\n  version   Int      @default(1)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([projectId])\n}\n\n/// 角色（人设卡 + 定妆照）\nmodel Character {\n  id          String      @id @default(cuid())\n  projectId   String\n  project     Project     @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  name        String\n  role        String // 剧作功能: protagonist | supporting | antagonist | utility\n  appearance  Json // 外貌: { hair, costume, facialMarkers, body, style }\n  personality Json // 性格: { habits, emotionalReactions, speechStyle, psychology }\n  costume     Json? // 场景化变装列表\n  refImageIds String[] // 精选定妆照(相对路径)\n  voiceId     String? // TTS音色映射\n  voiceName   String?\n  status      AssetStatus @default(DRAFTING)\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  @@index([projectId])\n}\n\n/// 场景（环境空镜）\nmodel Scene {\n  id          String      @id @default(cuid())\n  projectId   String\n  project     Project     @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  name        String // 如\"雨夜小巷\"\n  description String?     @db.Text\n  mood        String? // 情绪基调（影响灯光/BGM）\n  refImageIds String[] // 标准空镜图\n  status      AssetStatus @default(DRAFTING)\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  @@index([projectId])\n}\n\n/// 通用资产（道具/风格等）\nmodel Asset {\n  id        String      @id @default(cuid())\n  projectId String\n  project   Project     @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  type      AssetType\n  name      String\n  imageIds  String[]\n  meta      Json?\n  status    AssetStatus @default(DRAFTING)\n  createdAt DateTime    @default(now())\n  updatedAt DateTime    @updatedAt\n\n  @@index([projectId, type])\n}\n\n/// 集\nmodel Episode {\n  id        String   @id @default(cuid())\n  projectId String\n  project   Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  number    Int\n  title     String?\n  hookEnd   String? // 集尾悬念\n  status    String   @default(\"draft\")\n  finalPath String? // 成片视频路径\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  shots Shot[]\n\n  @@unique([projectId, number])\n}\n\n/// 分镜（核心工作单元）\nmodel Shot {\n  id            String     @id @default(cuid())\n  episodeId     String\n  episode       Episode    @relation(fields: [episodeId], references: [id], onDelete: Cascade)\n  sequence      Int // 镜头序号\n  sceneName     String? // 关联场景名\n  sceneId       String?\n  camera        Json // { angle, movement, shotSize }\n  action        String?    @db.Text // 画面动作描述\n  dialog        String? // 台词\n  dialogChar    String? // 说话角色名\n  dialogEmotion String? // 台词情绪\n  duration      Float // 目标时长(秒)\n  prompt7       Json? // 提示词7维\n  finalPrompt   String?    @db.Text // 组装后的完整提示词\n  refImages     String[] // 出图参考图（锁定角色定妆照/场景空镜，相对路径）\n  imagePath     String? // 分镜图\n  videoPath     String? // 视频片段\n  voicePath     String? // 配音\n  subtitlePath  String? // 该镜字幕\n  status        ShotStatus @default(PENDING)\n  retries       Int        @default(0)\n  error         String?    @db.Text\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n\n  @@index([episodeId, sequence])\n}\n\n/// 供应商配置（KV存储，设置页可写，优先于环境变量）\nmodel ProviderSetting {\n  key       String   @id // 如: ark.apiKey, kling.apiKey, llm.scriptProvider, image.provider ...\n  value     String   @db.Text\n  updatedAt DateTime @updatedAt\n}\n\n/// 所有AI任务统一追踪（含费用）\nmodel GenTask {\n  id             String     @id @default(cuid())\n  projectId      String?\n  project        Project?   @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  label          String? // 任务描述（UI 展示），如 \"剧本工坊·角色提炼\"\n  type           TaskType\n  provider       String // deepseek | doubao | seedream | kling | vidu | cosyvoice | minimax | ...\n  model          String\n  refType        String? // shot | character | scene | asset | episode\n  refId          String?\n  status         TaskStatus @default(QUEUED)\n  providerTaskId String? // 平台侧任务ID\n  input          Json? // 请求参数快照（费用估算）\n  cost           Float? // 估算费用(元)\n  error          String?    @db.Text\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  @@index([status])\n  @@index([projectId])\n}\n",
